def transform_string(n, s, t):
    if sorted(s) != sorted(t):
        return -1

    moves = []
    s = list(s)

    for i in range(n):
        for j in range(n - 1, i, -1):
            if s[j] == t[i]:
                for k in range(j, i, -1):
                    s[k], s[k - 1] = s[k - 1], s[k]
                    moves.append(k)
                break
            elif s[j - 1] == t[i]:
                s[j], s[j - 1] = s[j - 1], s[j]
                moves.append(j)
                break

    return len(moves), moves

# Example usage
