    print(" ".join(map(str, moves)))

import datetime

class Stack:

	def __init__(self):
		self.items = []

	def push(self, item):
		self.items.append(item)

	def pop(self):
		self.items.pop(-1)

	def is_empty(self):
		return self.items == []

	def peek(self):
		if not self.items == []:
			return self.items[-1]

	def get_stack(self):
		return self.items
