for _ in range(t):
	n = int(input())
	arr = list(map(int, input().split()))
	count_ = 0
	arr.reverse()
	s = Stack()
	for i in arr:
		if s.is_empty():
			s.push(i)
		elif s.peek() < i:
			count_ += 1
			s.push(i)
		else:
			while s.peek() >= i:
				s.pop()
				if s.is_empty():
					break
			if s.is_empty():
				s.push(i)
			elif s.peek() < i:
				count_ += 1
				s.push(i)
	print(count_)

