def solve(nums) -> bool:

    if nums.count(1) != 1:

        return False

    maxC = max(nums)

    if maxC > len(nums):

        return False

    if nums.count(maxC) > len(nums) - maxC + 1:

        return False

    idx1 = nums.index(1)

    nums = nums[idx1:] + nums[:idx1]

    for i in range(1,len(nums)):

        if nums[i]>nums[i-1]+1:

            return False

    return True





