#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while(t--){
        int n, m;
        cin >> n >> m;
        vector<vector<int>> grid(n, vector<int>(m));
        for(auto& row: grid){
            string s;
            cin >> s;
            for(int i=0;i<m;i++)
                row[i] = s[i]-'0';
        }

        // Mark the nice subrectangles
        vector<vector<int>> nice(n, vector<int>(m, 0));
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(grid[i][j]){
                    int bottom = n, right = m;
                    for(int k=i;k<n;k++){
                        if(!grid[k][j]){
                            bottom = k;
                            break;
                        }
                    }

                    for(int k=j;k<m;k++){
                        if(!grid[i][k]){
                            right = k;
                            break;
                        }
                    }

                    bool isNice = true;
                    for(int x=i+1;x<bottom;x++){
                        for(int y=j+1;y<right;y++){
                            if(nice[x][y])
                                isNice = false;
                        }
                    }
                    if(isNice){
                        for(int x=i;x<bottom;x++){
                            for(int y=j;y<right;y++){
                                nice[x][y] = 1;
                            }
                        }
                    }
                }
            }
        }

        // Check if any nice subrectangles intersect
        bool elegant = true;
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(nice[i][j]){
                    for(int x=max(0, i-1);x<min(n, i+2);x++){
                        for(int y=max(0, j-1);y<min(m, j+2);y++){
                            if(nice[x][y] && (x!=i || y!=j)){
                                elegant = false;
                                goto end;
                            }
                        }
                    }
                }
            }
        }

        end:
        if(elegant) cout << "YES\n";
        else cout << "NO\n";
    } 
}

