class Solution {
public:
	int maxPalindromesAfterOperations(vector<string>& r) {
		vi v(26);
		int n = len(r);
		rep(i, n)
		repa(c, r[i])
			v[c - 'a']++;
		int s1 = 0;
		int s = 0;

		rep(i, 26){
			s += v[i];
			if (v[i] % 2) s1++;
		}
		int s2 = s - s1;

		int d = 0;
		vi f(n);

		rep(i, n)
			f[i] = len(r[i]);

		D(s1, s2);

		sort(f, F2(a, b){
			return a < b;
		});
		rep(i, n)
		if (f[i] % 2 == 0){
			if (s2 >= f[i]){
				d++;
				s2 -= f[i];
				D(f[i], d, s1, s2);
			}
			else	
				D(f[i], s1, s2);
		}
		else{
			if (s1 and s2 >= f[i] - 1){
				d++;
				s1--;
				s2 -= f[i] - 1;

				D(f[i], d, s1, s2);
			}
			elif (s2 > f[i]){
				d++;
				s1++;
				s2 -= f[i] + 1;

				D(f[i], d, s1, s2);
			}
			else	
				D(f[i], s1, s2);
		}
		return d;;
	}
};

