import sys
import math

def countDigit(n):
	return math.floor(math.log(n, 10) + 1)

def boring_apartment(num):
	calculative_num = num % 10 - 1
	rest_num = calculative_num * 10
	if countDigit(num) == 4:
		return rest_num + 10
	if countDigit(num) == 3:
		return rest_num + 6
	if countDigit(num) == 2:
		return rest_num + 3
	if countDigit(num) == 1:
		return rest_num + 1
num_test = input()
for i in range(0, int(num_test)):
	inpt = input()
	print(boring_apartment(int(inpt)))

def isCousin(root, a, b):
	arr = [[None, -1], [None, -1]]
	parentCheck(root, a, b, arr, None, 0)
	return True if arr[0][0] != arr[1][0] and arr[0][1] == arr[1][1] else False

def parentCheck(root, a, b, arr, parent, level):
	if not root:
		return
	if root.data == a:
		arr[0][0] = parent
		arr[0][1] = level
	if root.data == b:
		arr[1][0] = parent
		arr[1][1] = level
	parentCheck(root.left, a, b, arr, root, level + 1)
	parentCheck(root.right, a, b, arr, root, level + 1)

