    public static long fac(long N, long mod) {

        if (N == 0)

            return 1;

        if(N==1)

            return 1;

        return ((N % mod) * (fac(N - 1, mod) % mod)) % mod;

    }





    static long power(long x, long y, long p) {



        // Initialize result

        long res = 1;



        // Update x if it is more than or

        // equal to p

        x = x % p;



        while (y > 0) {



            // If y is odd, multiply x

            // with result

            if (y % 2 == 1)

                res = (res * x) % p;



            // y must be even now

            y = y >> 1; // y = y/2

            x = (x * x) % p;

        }



        return res;

    }



    // Returns n^(-1) mod p

    static long modInverse(long n, long p) {

        return power(n, p - 2, p);

    }



    // Returns nCr % p using Fermat's

    // little theorem.

    static long nCrModPFermat(long n, long r,

                              long p) {



        if (n < r)

            return 0;

        // Base case

        if (r == 0)

            return 1;



        return ((fac(n, p) % p * (modInverse(fac(r, p), p)

                % p)) % p * (modInverse(fac(n - r, p), p)

                % p)) % p;

    }







    public static int find(int[] parent, int x) {

        if (parent[x] == x)

            return x;

        return find(parent, parent[x]);

    }



    public static void merge(int[] parent, int[] rank, int x, int y) {

        int x1 = find(parent, x);

        int y1 = find(parent, y);



        if (rank[x1] > rank[y1]) {

            parent[y1] = x1;





        } else if (rank[y1] > rank[x1]) {

            parent[x1] = y1;



        } else {

            parent[y1] = x1;

            rank[x1]++;



        }





    }





    public static long gcd(long a, long b) {

        if (b == 0)

            return a;



        return gcd(b, a % b);

    }







    static int power(int x, int y, int p)

    {



        int res = 1;

        x = x % p;



        while (y > 0) {



            if (y % 2 == 1)

                res = (res * x) % p;



            y = y >> 1;

            x = (x * x) % p;

        }



        return res;

    }



    // Returns n^(-1) mod p

    static int modInverse(int n, int p)

    {

        return power(n, p - 2, p);

    }



    // Returns nCr % p using Fermat's

    // little theorem.

    static int nCrModPFermat(int n, int r,

                             int p)

    {



        if (n<r)

            return 0;

        // Base case

        if (r == 0)

            return 1;



        // Fill factorial array so that we

        // can find all factorial of r, n

        // and n-r

        int[] fac = new int[n + 1];

        fac[0] = 1;



        for (int i = 1; i <= n; i++)

            fac[i] = fac[i - 1] * i % p;



        return (fac[n] * modInverse(fac[r], p)

                % p * modInverse(fac[n - r], p)

                % p)

                % p;

    }







    public static long[][] ncr(int n,int r)

    {

        long[][] dp=new long[n+1][r+1];

        for(int i=0;i<=n;i++)

            dp[i][0]=1;

        for(int i=1;i<=n;i++)

        {

            for(int j=1;j<=r;j++)

            {

                if(j>i)

                    continue;

                dp[i][j]=dp[i-1][j-1]+dp[i-1][j];

            }

        }



        return dp;



    }





