class Solution:

	def longestPalinSubseq(self, S):

		def lcs(x, y, m, n):
			dp = [[-1 for i in range(n + 1)] for j in range(m + 1)]
			for i in range(0, m):
				for j in range(0, n):
					if i == 0 or j == 0:
						dp[i][j] = 0
			for i in range(1, m + 1):
				for j in range(1, n + 1):
					if x[i - 1] == y[j - 1]:
						dp[i][j] = 1 + dp[i - 1][j - 1]
					else:
						dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
			return dp[m][n]
		S1 = S[::-1]
		n = len(S)
		m = len(S1)
		y = lcs(S, S1, n, m)
		return y

