def center_of_island(row):
    row_center_odd = [None for _ in range(N)]
    row_center_even = [None for _ in range(N)]
    row_center_odd[0] = 1 if row[0] == 'L' else 0
    row_center_even[0] = 1 if row[1] == 'L' else 0
    for i in range(1, N - 1):
        row_center_odd[i] = [0, 0][row[i-1] == 'L'] + [0, 1][row[i] == 'L'] + [0, 0][row[i+1] == 'L']
        row_center_even[i] = [0, 0][row[i-1] == 'L'] + [0, 0][row[i] == 'L'] + [0, 1][row[i+1] == 'L']
    row_center_odd[N-1] = 1 if row[N-2] == 'L' else 0
    row_center_even[N-1] = 1 if row[N-1] == 'L' else 0
    row_c = []
    for row_center in [row_center_odd, row_center_even]:
        max_size = 0
        res = 0
        for value in row_center:
            if value == 3:
                max_size += 1
            else:
                if max_size > res:
                    res = max_size
                max_size = 0
        if max_size > res:
            res = max_size
        row_c.append(res)
    return [2] if 3 in row_c else row_c

