def solve(X, Y, S):
    def remove_substring(s, sub):
        stack = []
        for char in s:
            if stack and stack[-1] + char == sub:
                stack.pop()  # Remove the last character from the stack
            else:
                stack.append(char)  # Add the current character to the stack
        return ''.join(stack)

    if X >= Y:
        # Prioritize removing "pr"
        score = S.count('pr') * X
        remaining_string = remove_substring(S, 'pr')
        score += remaining_string.count('rp') * Y
    else:
        # Prioritize removing "rp"
        score = S.count('rp') * Y
        remaining_string = remove_substring(S, 'rp')
        score += remaining_string.count('pr') * X

    return score

