def numBusesToDestination(self, routes, S, T):
        from collections import defaultdict
        g = defaultdict(list)
        for k, v in enumerate(routes):
            for n in v:
                g[n].append(k)

        res = [get_neibours(g, S, k) for k in range(len(routes)) if S in routes[k]
        in_q = set(S)
        while S != T:
            n_res = set()
            for s in res[-1]:
                n_res = n_res.union(set(g[s]))
            res.append(n_res - in_q)
            in_q = in_q.union(res[-1])
            if res[-1] == set():
                return -1
        return len(res) - 1

    def get_neibours(g, s, i):
        res = set()
        for j in g[s]:
            if j == i:
               continue 
            res = res.union(set(g[j]))
        return res

