def breadthFirstSearch(end,graph,check,current):
    check.add(current)
    queue = [current]
    steps = Counter({current:0})
    for node in queue:

        temp = Counter()
        print(node + "-" + str(len(queue)))
        queue = queue[1:]
        for child in graph[node]:
            if not child in check:
                temp[child] = 1 + steps[node]
        queue = [i for i,j in temp.items() if j==min(temp.values())]+queue
