def dfs(node, parent):
    global edges
    global color
    color[node] = 1 - color[parent]
    for edge in edges:
        if edge[0] == node:
            if color[edge[1]] == -1:
                dfs(edge[1], node)
            elif color[edge[1]] == color[node]:
                return False
        elif edge[1] == node:
            if color[edge[0]] == -1:
                dfs(edge[0], node)
            elif color[edge[0]] == color[node]:
                return False
    return True

