import sys

def decode_genome(n, s):
    counts = {'A': 0, 'C': 0, 'G': 0, 'T': 0}
    unknown_count = 0

    for c in s:
        if c == '?':
            unknown_count += 1
        elif c in counts:
            counts[c] += 1

    total_unknown = n - (counts['A'] + counts['C'] + counts['G'] + counts['T'])

    if total_unknown < 0 or (n % 4!= 0):
        return "==="

    target_count = n // 4

    excess_count = {}
    for k, v in counts.items():
        excess_count[k] = v - target_count

    for c in excess_count:
        if excess_count[c] > 0:
            counts[c] = target_count
            unknown_count += excess_count[c]
        elif excess_count[c] < 0:
            need = -excess_count[c]
            counts[c] += need
            unknown_count -= need

    if unknown_count!= 0:
        return "==="

    result = []
    for c in s:
        if c == '?':
            found = False
            for k, v in counts.items():
                if v < target_count:
                    result.append(k)
                    counts[k] += 1
                    found = True
                    break
            if not found:
                return "==="

        else:
            result.append(c)

    return "".join(result)


