    int ans = 0;
    REP(i,0,N) {
      int j = i;
      ll prod = 1;
      while (j < N) {
        if (x[j] > 1) {
          prod *= x[j];
          if (prod < k) ans++;
          j++;
        } else {
          if (prod < k) ans += nxt[j] - j + 1;
          j = nxt[j] + 1;
        }
        if (prod >= k) break;
      }
    }
    return ans;
  }
};

