def check_weights(t, test_cases):
    results = []
    for n, a, b, c, d in test_cases:
        min_weight_per_grain = a - b
        max_weight_per_grain = a + b
        total_min_weight = n * min_weight_per_grain
        total_max_weight = n * max_weight_per_grain
        possible_total_weight_range = (c - d, c + d)

        if total_min_weight <= possible_total_weight_range[1] and total_max_weight >= possible_total_weight_range[0]:
            results.append("Yes")
        else:
            results.append("No")
    return "\n".join(results)

