def min_cards_to_flip(s):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    odd_digits = {'1', '3', '5', '7', '9'}

    # Collect all cards with vowels and all cards with odd digits
    cards_with_vowels = [i for i, char in enumerate(s) if char in vowels]
    cards_with_odd_digits = [i for i, char in enumerate(s) if char in odd_digits]

    # Calculate the minimum number of cards to flip
    if not cards_with_vowels:
        return 0

    cards_to_flip = set(cards_with_vowels) | set(cards_with_odd_digits)
    return len(cards_to_flip)


# Example usage:
