def find_sum(num):
	deg = 0
	odd = 0
	even = 0
	x = num
	while x > 0:
		if deg % 2 == 0:
			odd += min(1 << deg, x)
		else:
			even += min(1 << deg, x)
		x -= 1 << deg
		deg += 1
	return odd * odd + even * (even + 1)
