class Solution:

	def lcmAndGcd(self, a, b):
		lcm_a = a
		lcm_b = b
		if a == 0 or b == 0:
			return (0, 0)
		gcd = 1
		while a > 0 and b > 0:
			if a > b:
				a = a % b
			else:
				b = b % a
		if a == 0:
			gcd = b
		else:
			gcd = a
		lcm = lcm_a * lcm_b // gcd
		return (lcm, gcd)

