class Solution {
public:
    int minimumTime(vector<vector<int>>& grid) {
        if (grid[0][1] > 1 && grid[1][0] > 1) return -1;
        int m = grid.size();
        int n = grid[0].size();
        priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> pq;
        bool visited[m][n];
        int dist[m][n];
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                dist[i][j] = 1e9;
                visited[i][j] = false;
            }
        }
        dist[0][0] = 0;
        pq.push({0, {0, 0}});
        while (!pq.empty()) {
            auto pp = pq.top();
            int d = pp.first;
            int x = pp.second.first;
            int y = pp.second.second;
            pq.pop();
            if (x == m - 1 && y == n - 1) {
                return d;
            }
            if (visited[x][y]) continue;
            visited[x][y] = true;
            if (x + 1 < m && !visited[x + 1][y]) {
                int t = max(grid[x + 1][y], dist[x][y] + 1);
                if (t % 2 != (x + 1 + y) % 2) ++t;
                if (dist[x + 1][y] > t) {
                    dist[x + 1][y] = t;
                    pq.push({t, {x + 1, y}});
                }
            }
            if (x - 1 >= 0 && !visited[x - 1][y]) {
                int t = max(grid[x - 1][y], dist[x][y] + 1);
                if (t % 2 != (x - 1 + y) % 2) ++t;
                if (dist[x - 1][y] > t) {
                    dist[x - 1][y] = t;
                    pq.push({t, {x - 1, y}});
                }
            }
            if (y + 1 < n && !visited[x][y + 1]) {
                int t = max(grid[x][y + 1], dist[x][y] + 1);
                if (t % 2 != (x + 1 + y) % 2) ++t;
                if (dist[x][y + 1] > t) {
                    dist[x][y + 1] = t;
                    pq.push({t, {x, y + 1}});
                }
            }
            if (y - 1 >= 0 && !visited[x][y - 1]) {
                int t = max(grid[x][y - 1], dist[x][y] + 1);
                if (t % 2 != (x - 1 + y) % 2) ++t;
                if (dist[x][y - 1] > t) {
                    dist[x][y - 1] = t;
                    pq.push({t, {x, y - 1}});
                }
            }
        }
        return 0;
    }
};

