from collections import defaultdict

def is_substring(main_str, substr):
    """Check if substr is a substring of main_str."""
    return substr in main_str

def solve(n, strings):
    """Solve the problem."""
    # Create a graph where each string is a node
    graph = defaultdict(list)
    in_degree = {string: 0 for string in strings}

    # Build the graph
    for i in range(n):
        for j in range(n):
            if i!= j and is_substring(strings[j], strings[i]):
                graph[strings[i]].append(strings[j])
                in_degree[strings[j]] += 1

    # Topological sorting
    queue = [string for string in strings if in_degree[string] == 0]
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if there's a cycle (i.e., not all nodes are reachable)
    if len(result)!= n:
        return "NO"

    return "YES\n" + "\n".join(result)

