private:
    int root[100];
public:
    UnionFind(){
        for( int i =0 ; i<100 ; i++ ){
            root[i]=i;
        }
    };
    int GetRoot(int x){
        while(x != root[x]){
            x = root[x];
        }
        return x;
    }

    void Union(int a ,int b){
        a = GetRoot(a);
        b = GetRoot(b);
        if(a == b){
            return ;
        }
        root[a] = b;

    }
    bool Isapart(int a ,int b){
        int aroot = GetRoot(a);
        int broot = GetRoot(b);
        return aroot!=broot;
    }
    void UnionMsithsize(int a,int b,int *size){
        a = GetRoot(a);
        b = GetRoot(b);
        if(a == b){
            return ;
        }
        if(size[a]>size[b])
            swap(a,b);
        root[a] = b;
        size[b]+=size[a];
    }

};

