from collections import defaultdict

MOD = 1000000007

def count_ways(n, sardines):
    # Create a graph where two sardines are on bad terms
    graph = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if sardines[i][0] * sardines[j][0] + sardines[i][1] * sardines[j][1] == 0:
                graph[i].append(j)
                graph[j].append(i)

    def dfs(node, visited, parent):
        visited.add(node)
        count = 1
        for neighbor in graph[node]:
            if neighbor!= parent and neighbor not in visited:
                count += dfs(neighbor, visited, node)
        return count

    # Find all independent sets
    independent_sets = []
    for i in range(n):
        if not graph[i]:
            independent_sets.append([i])
        else:
            # Find an independent set containing the current node
            for neighbor in graph[i]:
                visited = set()
                count = dfs(neighbor, visited, -1)
                independent_sets.append(list(visited))

    # Count the total number of sets
    total_count = 2 ** len(independent_sets)
    return total_count % MOD

