def get_x_and_y(n: int) -> str:
    x = 0
    y = 0
    for i in range(len(str(n))):
        if n % 10 == 9:
            x += 9 * 10 ** i
            y += 0 * 10 ** i
        else:
            x += (n % 10 + 1) * 10 ** i
            y += 1 * 10 ** i
        n //= 10
    return str(x) + " " + str(y)

