def get_placements(grid: List[list], c0: int) -> List[int]:
    r = [0] * 9
    c = [0] * 9
    for i in range(0, 9):
        for j in range(0, 9):
            r[i] |= (grid[i][j] << (grid[i][j] - 1))
            c[j] |= (grid[i][j] << (grid[i][j] - 1))
    # '^' is XOR
    ret_list = [1 << (x - 1) for x in range(1, 10)]
    for i in range(0, 9):
        ret_list[i] ^= (r[c0] | c[i])
    return ret_list

def dfs(grid: List[list], cnt: int) -> tuple:
    if cnt == 0:
        return True, grid
    ones_list = [0] * 81
    cnt_list = [0] * 81
    for i in range(80, -1, -1):
        r = i // 9
        c = i % 9
        cnt_list[i] = len(get_placements(grid, r))
        if cnt_list[i] == 1:
            continue
        ones_list[i] = len(get_placements(grid, r))
    c0 = ones_list.index(min(ones_list))
    r0 = c0 // 9
    c0 = c0 % 9
    pv = get_placements(grid, r0)
    for p in pv:
        grid[r0][c0] = int(p)
        rt, rgrid = dfs(grid, cnt - 1)
        if rt:
            return True, rgrid
    grid[r0][c0] = 0
    return False, grid

def solve(grid: List[list]) -> List[list]:
    cnt = 0
    for i in range(0, 9):
        for j in range(0, 9):
            if 1 <= grid[i][j] <= 9:
                cnt += 1
    rt, ret_grid = dfs(grid, cnt)
    return ret_grid

