	if i1 < 0 or j1 < 0 or j1 >= m or (i1 >= n) or (i1 < j1) or (ans[i1][j1] != -1) or (val <= 0):
		return val
	ans[i1][j1] = p1
	val = solve(i1 - 1, j1, p1, val - 1)
	if val <= 0:
		return val
	val = solve(i1, j1 - 1, p1, val)
	if val <= 0:
		return val
	val = solve(i1 + 1, j1, p1, val)
	if val <= 0:
		return val
	val = solve(i1, j1 + 1, p1, val)
	return val
