class Solution {
public:

    int dx[4] = {0,1,0,-1};
    int dy[4] = {1,0,-1,0};

    bool possible(int x,int y,int end_x,int end_y)
    {
       if(x < 0 || x >= end_x || y < 0 || y >= end_y)
           return false;

       return true;
    }

    int minimumObstacles(vector<vector<int>>& grid) {


        priority_queue<pair<int,pair<int,int> >, vector< pair<int,pair<int,int>>> , greater<pair<int,pair<int,int>> > >pq;

        int dx[4] = {0,1,0,-1};
        int dy[4] = {1,0,-1,0};

        int ans = -1;

        vector<vector<bool>>visited(grid.size(),vector<bool>(grid[0].size(),false));

        pq.push({0,{0,0}});

        while(!pq.empty())
        {

            auto top = pq.top();
            pq.pop();

            int x_cord = top.second.first;
            int y_cord = top.second.second;
            int obs = top.first;

            if(x_cord == grid.size()-1 && y_cord == grid[0].size()-1)
                return obs;

            if(visited[x_cord][y_cord])
                continue;

            visited[x_cord][y_cord] = true;


           // cout<<"x is "<<x_cord<<" and y is "<<y_cord<<"\n";

            for(int i = 0 ; i < 4; i++)
            {
                int new_x = x_cord+dx[i];
                int new_y = y_cord+dy[i];


                if( possible(new_x,new_y,grid.size(),grid[0].size()) && !visited[new_x][new_y] )
                { 

                    if(grid[new_x][new_y] == 1)
                    {
                        pq.push({obs+1,{new_x,new_y}});  
                    }
                    else
                    {
                     pq.push({obs,{new_x,new_y}});     
                    } 
                }
            }
        }

        return ans;
    }
};

