A:

The problem is in the calculation of the sum:
for(int j=0;j<n;++j){
    if(v[j]%2!=1){
        sum+=v[j];
    }
}

The loop iterates over the elements of v. But later on some of them are deleted from a and b, so there is a mismatch between the original index i and the index where the number is stored after the update of a and b.
In fact this line:
sum+=v[sum/2];

is always used, but the index sum/2 corresponds to an element deleted from a or b.
Furthermore, there is no need to calculate the sum of all even integers, so you should do a preprocessing step to calculate it, and use the result the same way in the second loop.
EDIT:
Here is one possible solution.
It uses a single array with all the elements that might be present in either a or b, so you can calculate the sum (calculating both sums is unnecessary), but then use this pre-calculated sum to know where to insert the elements from a and b.
#include<iostream>
#include<set>

using namespace std;

int main()
{
    set<int> a,b,c,v;
    int t,n;
    cin>>t;
    while(t--){
        cin>>n;
        int vals[]={0};
        int sum_odd=0,sum_even=0;
        for(int i=0;i<n;++i){
            cin>>vals[i];
            vals[i]+=n;
        }
        int counter=0;
        for(int i=0;i<n;++i){
            if(vals[i]%2!=1){
                sum_odd+=vals[i];
                ++counter;
            }else{
                sum_even+=vals[i];
                ++counter;
            }
        }
        for(int i=0;i<counter;++i){
            int v = vals[i]/2;
            v&=1;
            while(a.find(v)!=a.end() && b.find(v)!=b.end()){
                swap(v,a[v]);
                swap(v,b[v]);
                v&=1;
            }
        }
        for(int i=0;i<n;++i){
            c.insert(vals[i]/2);
        }
        cout<<sum_odd<<"<"<<sum_even<<">";
    }
}

