def digits(n):
    return len(str(abs(n)))

def count(N, K):
    left, right = 1, N
    while left <= right:
        mid = (left + right) // 2
        if not K - digits(mid) // 2: # digits(mid) is the total number of digits in the number mid
            return mid
        elif K - digits(mid) // 2 < 0: # if n < K digits
            right = mid - 1
        else: # if n > K digits
            left = mid + 1
    return -1

def main():
    N = int(input())
    K = int(input())
    print(count(N, K))

