class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        from sortedcontainers import SortedList
        prev = SortedList()  # (nums[i]-i, max_sum)
        values = {}
        for i, num in enumerate(nums):
            if num <= 0:
                continue
            key = num - i
            idx = prev.bisect_right(key)
            if idx == 0:
                max_sum = num
            else:
                max_sum = num + values[prev[idx-1]]
            useful = True
            while idx < len(prev):
                if key < prev[idx]:
                    if max_sum < values[prev[idx]]:
                        break
                    del values[prev[idx]]
                    prev.pop(index=idx)
                elif key > prev[idx]:
                    if max_sum <= values[prev[idx]]:
                        # not useful
                        useful = False
                        break
                    idx += 1
                else: # equal
                    if max_sum <= values[prev[idx]]:
                        useful = False
                    break
            if not useful:
                continue
            idx = prev.bisect_left(key)
            if idx < len(prev) and prev[idx] == key:
                values[prev[idx]] = max_sum
            else:
                prev.add(key)
                values[key] = max_sum
        return max(nums) if len(prev) == 0 else values[prev[-1]]

