class Solution:
    def isAlienSorted(self, words, order):
        """
        :type words: List[str]
        :type order: str
        :rtype: bool
        """
        unchecked = list(range(len(words)))
        k = 0
        while len(unchecked) > 1:
            for i, w in enumerate(unchecked):
                if i > 0 and i < len(unchecked):
                    pre = unchecked[i-1]
                    if k < len(words[pre]):
                        if k < len(words[unchecked[i]]):
                            if order.index(words[unchecked[i]][k]) < order.index(words[pre][k]):
                                return False
                            elif order.index(words[unchecked[i]][k]) > order.index(words[pre][k]):
                                unchecked.remove(pre) 
                        else:
                            if unchecked[0] < unchecked[i]:
                                return False
                            unchecked.remove(unchecked[i])
                            continue
                    else:
                        unchecked.remove(pre)
                        continue
            k += 1
        return True

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* insertGreatestCommonDivisors(ListNode* head) {
        ListNode* ptr=head;
        while(ptr->next){
            int l=ptr->val,r=ptr->next->val;
            ListNode* temp=ptr->next;
            ptr->next=new ListNode(gcd(l,r));
            ptr->next->next=temp;
            ptr=temp;
        }
        return head;
    }
};

