def solve(n, arr):
	cur = arr[0]
	transformed = [0]
	for i in range(1, n):
		transformed.append(max(transformed[i - 1], arr[i] - cur))
		cur = min(cur, arr[i] - transformed[i])
	cur = arr[-1]
	for i in range(n - 1, -1, -1):
		if arr[i] < transformed[i]:
			return False
	return True
