class Solution:

	def isAnagram(self, a, b):
		a_dict = {}
		for i in a:
			if i not in a_dict:
				a_dict[i] = 1
			else:
				a_dict[i] += 1
		b_dict = {}
		for i in b:
			if i not in b_dict:
				b_dict[i] = 1
			else:
				b_dict[i] += 1
		return a_dict == b_dict

