def max_two_gram(s):
    max_count=0
    max_gram=""
    count_dict={}

    #count frequencies
    for i in range(len(s)-1):
        two_gram = s[i:i+2]
        if two_gram in count_dict:
            count_dict[two_gram]+=1
        else:
            count_dict[two_gram]=1

    #find max frequency pair
    for key,value in count_dict.items():
        if value>max_count:
            max_count=value
            max_gram=key

    return max_count,max_gram


