	for i in range(1, n):
		a[i] += a[i - 1]
	anew = [(a[0], 0)]
	for i in range(n):
		if anew[-1][0] < a[i]:
			anew.append((a[i], i))
	ma = anew[-1][0]
	s = a[-1]
	ans = []
	for i in range(m):
		if s <= 0:
			if ma >= x[i]:
				h = 1
			else:
				ans.append(-1)
				continue
		else:
			h = math.ceil(x[i] / s)
		l = 0
		while l < h:
			mid = (h + l) // 2
			if s * mid + ma >= x[i]:
				h = mid
			else:
				l = mid + 1
		preans = h * n
		pre = s * h
		ind = bisect.bisect_left(anew, (x[i] - pre, 0))
		ans.append(preans + anew[ind][1])
