/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Solution {
    public List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        List<Integer> e1 = new ArrayList<>();
            ele(root1, e1);
        List<Integer> e2 = new ArrayList<>();
        ele(root2, e2);
        List<Integer> ans = new ArrayList<>();

        int x1 = 0, x2 = 0;

        while (x1 < e1.size() && x2 < e2.size()) {
            if (e1.get(x1) < e2.get(x2)) {
                ans.add(e1.get(x1));
                x1++;
            } else {
                ans.add(e2.get(x2));
                x2++;
            }
        }

        while (x1 < e1.size()) {
            ans.add(e1.get(x1));
            x1++;
        }


        while (x2 < e2.size()) {
            ans.add(e2.get(x2));
            x2++;
        }

        return ans;
    }

    private static void ele(TreeNode root, List<Integer> l) {
        if (root == null) {
            return;
        }

        ele(root.left, l);
        l.add(root.val);
        ele(root.right, l);
    }



}

def place_hotels(n, k):
    # The grid initialization with no hotels ('.')
    grid = [['.' for _ in range(n)] for _ in range(4)]

    # Place hotels horizontally if we have more or exactly 2 hotels.
    if k >= 2:
        for i in range(k // 2):
            grid[1][i + 1] = '#'
            grid[2][i + 1] = '#'
        k -= 2

    # Place remaining hotels vertically in the center column if k > 0.
    if k > 0:
        if k == 1:
            grid[1][n // 2] = '#'
        elif k == 3:
            grid[1][n // 2] = '#'
            grid[2][n // 2] = '#'
        else:
            for i in range(1, 3):
                grid[i][n // 2] = '#'
            k -= 2

    # Print the result
    print("YES")
    for row in grid:
        print("".join(row))

# Sample Inputs
