import collections

class Solution:
    def countPattern(self, nums, pattern):
        cc= collections.Counter()
        k = len(pattern[pattern==1])
        for i in range(max(0,len(nums)-len(pattern))):

            j = i + len(nums) - len(pattern)
            # fill the list with integers - 1,0,1 where -1 is if first index is bigger, 0 if equal,1 if second is bigger
            fill =  [ ( nums[x+k] - nums[x] , nums[x+k] ,nums[x] , nums[x+k+1] ) for x in range (len(nums) - len(pattern))]
            count = 0
            # If our current sequence matches our criteria, search for the next match. 
            for n,p,o,f in fill :
                if ( pattern[0] == 0  and  n == 0  ) :
                    count += 1
                elif ( pattern[0] == 1  and  n == 1  ) :
                    count += 1
                elif ( pattern[0] == -1  and  n == 1  ) :
                    if pattern[1] == 1  and  f > o:
                        count += 1
                    elif pattern[1] == 0  and  f == o:
                        count += 1
                    elif pattern[1] == -1  and  f < o:
                        count += 1
            cc.setdefault((i,j),0)
            cc[(i,j)] = cc[(i,j)] + count
        return max (cc.values())

