    for char in set(s):
        if s.count(char) % 2 != 0:
            count_odd += 1
    return count_odd <= 1

def solve(s):
    if is_palindrome(s):
        return "YES"
    if can_form_palindrome(s):
        return "YES"
    return "NO"

if __name__ == "__main__":
    s = input()
    print(solve(s))

