Class Solution(object):
    def can_paint_cells(self, n:int, m:int, k:int, colors_to_use: List[int])->bool:
        if max(colors_to_use) > (n-1) / k:
            return False

        colors_count = [0] * m

        color = 0
        consecutive_cells = 0
        for cell in colors_to_use:
            if cell == colors_count[color]:
                consecutive_cells += 1
                if consecutive_cells == k:
                    color += 1
                    consecutive_cells = 1
                    colors_count[color] += 1
            else:
                consecutive_cells = 1
                colors_count[color] += 1

        for count in colors_count:
            if count < (n-1) / k:
                return False
        return True

    def paint_coloring(self, t: int, test_cases: List[tuple])->List[str]:
        results = []
        for i in range(t):
            n, m, k = test_cases[i][0], test_cases[i][1], test_cases[i][2]
            colors_to_use = test_cases[i][3]
            result = "YES" if self.can_paint_cells(n, m, k, colors_to_use) else "NO"
            results.append(result)
        return results

