Input format:
The only input given via STDIN is the root node of tree, given by its level order as separate line of integers, and every node's value is followed by a single white space.

Output format:
The function height should return an integer representing the height of the tree.

Solution:-

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def insert(root, key):
    if root is None:
        return TreeNode(key)
    else:
        if root.val < key:
            root.right = insert(root.right, key)
        else:
            root.left = insert(root.left, key)
    return root

def levelOrderTraversal(root):
    queue = []
    queue.append(root)
    while queue:
        node = queue.pop(0)
        print(node.val, end=' ')
        if node.left is not None:
            queue.append(node.left)
        if node.right is not None:
            queue.append(node.right)

def height(root):
    if root is None:
        return 0
    else:
        left_height = height(root.left)
        right_height = height(root.right)
        return 1 + max(left_height, right_height)

if __name__ == '__main__':
    root = None
    keys = [int(num) for num in input().strip().split()]
    for key in keys:
        root = insert(root, key)

    # Print the level order traversal of the constructed tree
    levelOrderTraversal(root)
    # Print the height of the tree
    print("Height of the given binary tree:", height(root))

