def searchP(p, arr, n):
	(low, high) = (0, n - 1)
	ans = -1
	while low <= high:
		mid = low + (high - low) // 2
		if arr[mid][1] > p:
			ans = mid
			high = mid - 1
		else:
			low = mid + 1
	if ans == -1:
		return -1
	return max(0, arr[ans][0] - p)
