class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def moveZeroes(head):
    if not head or not head.next:
        return head

    zero = None
    non_zero = None
    new_head = None

    while head:
        if head.data == 0:
            if not zero:
                zero = head
                new_head = zero
            else:
                zero.next = head
                zero = zero.next
        else:
            if not non_zero:
                non_zero = head
                if not new_head:
                    new_head = non_zero
            else:
                non_zero.next = head
                non_zero = non_zero.next

        head = head.next

    if zero:
        zero.next = None
    if non_zero:
        non_zero.next = None
    if zero and non_zero:
        zero.next = new_head
        new_head = non_zero

    return new_head

from collections import Counter

class Solution:

	def numberOfSubarrays(self, nums: List[int], k: int) -> int:
		oddCounts = []
		oddCount = 0
		for num in nums:
			if num % 2 == 1:
				oddCount += 1
			oddCounts.append(oddCount)
		oddCountsIdxs = Counter(oddCounts)
		nice = 0
		for num in oddCounts:
			nice += oddCountsIdxs[num - k]
		nice += oddCountsIdxs[k]
		return nice

