using namespace std;



class BS {

public:

    BS() {

        for (int i =0 ; i < n; i++) {

            a[i] = 0;

        }

    }



    int get(int pos) {

        return (a[pos / 64] >> (pos % 64)) & 0x1;

    }



    void set(int pos) {

        a[pos / 64] |= ((1ull) << (pos % 64));

    }



    void clr(int pos) {

        a[pos / 64] &= ~(u64)((1ull) << (pos % 64));

    }



    void flip(int start, int end) {

        for (int i = start; i <= end; i++) {

            if (i % 64 == 0 && i + 64 < end) {

                a[i/64] ^= (u64)(-1);

                i += 63;

                continue;

            }

            if (get(i)) {

                clr(i);

            } else {

                set(i);

            }

        }

    }



    int find0(u64 buck, int pos) {

        buck >>= pos;

        if (pos && buck == ((1ull << (64 - pos)) - 1)) {

            return -1;

        }

        buck ^= u64(-1);

        int res = __builtin_ctzll(buck);

        return res;

    }



    int find0(int pos) {

        if (pos % 64) {

            int res = find0(a[pos/64], pos % 64);

            if (res != -1) {

                return pos + res;

            }

            pos += 64 - pos % 64;

        }

        for (;;) {

            if (a[pos/64] == (u64(-1))) {

                pos+=64;

                continue;

            }

            return find0(a[pos/64], 0) + pos;

        }

    }



    int find1(u64 buck, int pos) {

        buck >>= pos;

        if (buck == 0) {

            return -1;

        }

        int res = __builtin_ctzll(buck);

        return res;

    }



    int find1(int pos) {

        if (pos % 64) {

            int res = find1(a[pos/64], pos % 64);

            if (res != -1) {

                return pos + res;

            }

            pos += 64 - pos % 64;

        }

        for (;;) {

            if (a[pos/64] == 0) {

                pos+=64;

                continue;

            }

            return find1(a[pos/64], 0) + pos;

        }

    }



    void add(int pos) {

        int fz = find0(pos);

        flip(pos, fz);

    }



    void ext(int pos) {

        int fo = find1(pos);

        flip(pos, fo);

    }



    int ans() {

        for (int i = n - 1; i >= 0; i--) {

            if (a[i] == 0) {

                continue;

            }



            return i * 64 + 63 - __builtin_clzll(a[i]);

        }



        return 0;

    }



    void dump() {

//        for (int i = 0; i < 128 + 64; i++) {

//            cout << get(i);

//            if ((i + 1) % 64 == 0) {

//                cout << ",";

//            }

//        }

//        cout << "\n";

    }



    static const int n = 3200;

    u64 a[BS::n];

};



void solve() {

    int n, m;

    cin >> n >> m;

    vector<int>a(n);

    auto bs = BS();



    for (int i = 0; i < n; i++) {

        cin >> a[i];

        bs.add(a[i]);

        bs.dump();

    }



    for (int i =0; i < m; i++) {

        itn x, y;

        cin >> x >> y;

        x--;

        bs.ext(a[x]);

        bs.dump();

        a[x] = y;

        bs.add(a[x]);

        bs.dump();

        cout << bs.ans() << "\n";

    }

}



