static boolean[] vowels = { false, false, false, false, false, true };
public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    while (s.hasNextLine()) {
        String line = s.nextLine();
        if (line.length() > 1) {
            System.out.print(replace(line).replaceAll("^\\s+|\\s+$", "").trim() + System.getProperty("line.separator"));
        }
    }
}

public static String replace(String line) {
    StringBufferBuffer line = new StringBufferBuffer();
    for (int i = 0; i < line.length(); i++) {
        char c = line.charAt(i);
        if (Character.isUpperCase(c)) {
            c = Character.lowerCase(c);
        } else if (isVowel(c)) {
            continue;
        }
        if (Character.isLowerCase(c)) {
            c = (char) (95 + Character.toUpperCase(c));
        }
        line.append(c);
    }
    return line.toString();
}

public static boolean isVowel(char ch) {
    return vowels[(int) ch];
}



