def is_Possible(self, grid):
        n = len(grid)
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    return self.is_Possible_helper(grid, i, j, n)
        return False

    def is_Possible_helper(self, grid, i, j, n):
        if i == n or j == n or i < 0 or j < 0 or grid[i][j] == 0:
            return False
        if grid[i][j] == 2:
            return True
        grid[i][j] = 0
        return self.is_Possible_helper(grid, i-1, j, n) or self.is_Possible_helper(grid, i+1, j, n) or self.is_Possible_helper(grid, i, j-1, n) or self.is_Possible_helper(grid, i, j+1, n)

