    public static void computeTaskDurations(int[] startTimes, int[] endTimes, int[] durations) {
        int n = startTimes.length;
        int[] taskDuration = new int[n];  // Array to store the duration of each task
        int[] queue = new int[n + 1];    // Queue to store the task start times
        Arrays.fill(queue, -1);
        for (int i = 0; i < n; i++) {
            // Find the index where the current task should be placed in the queue
            int index = Arrays.binarySearch(queue, endTimes[i]);
            if (index < 0) {
                index = ~index;
            }
            queue[index] = startTimes[i];
            // Calculate the duration of the current task
            durations[i] = endTimes[i] - queue[index];
            // Remove the task from the queue if it's not at the front
            while (index > 0 && queue[index - 1] <= endTimes[i]) {
                taskDuration[index-1] = durations[i];
                queue[index - 1] = -1;
                --index;
            }
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int n = reader.nextInt();
            int[] startTimes = new int[n];
            int[] endTimes = new int[n];
            for (int i = 0; i < n; i++) {
                startTimes[i] = reader.nextInt();
            }
            for (int i = 0; i < n; i++) {
                endTimes[i] = reader.nextInt();
            }
            int[] durations = new int[n];
            computeTaskDurations(startTimes, endTimes, durations);
            // Print the duration of each task
            for (int i = 0; i < n; i++) {
                System.out.print(durations[i] + " ");
            }
            System.out.println();
        }
    }
}

