def factorSum(N):
    if N == 1:
        return 1

    ans = 1 + N
    i = 2

    while i * i <= N:
        if N % i == 0:
            ans += i
            cntPair = N // i
            if i != cntPair:
                ans += cntPair
        i += 1

    return ans

