class Solution {
public:
    int numberOfPairs(vector<vector<int>>& points) {
        sort(all(points), [&](auto &a, auto &b) {
            if (a[1] == b[1]) return a[0] < b[0];
            return a[1] > b[1];
        });
        // debug(points);
        int n = points.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int x1 = points[i][0], y1 = points[i][1];
            set<int> s;
            for (int j = i + 1; j < n; j++) {
                int x2 = points[j][0], y2 = points[j][1];
                if (x2 < x1) continue;
                // debug(x1, y1, x2, y2);
                if (s.empty() or x2 < *s.begin()) {
                    ans++;
                }
                s.insert(x2);
            }
        }
        return ans;
    }
};

class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int[] diffA = new int[2*limit+2];
        for(int i=0;i<n/2;i++){
            int ma = Math.max(nums[i],nums[n-1-i]);
            int mi = Math.min(nums[i],nums[n-1-i]);
            diffA[ma+mi]++;
            diffA[ma+mi+1]--;
            ma = ma + limit;
            mi = mi + 1;
            diffA[mi]++;
            diffA[ma+1]--;
        }
        int max =0;
        for(int i=1;i<diffA.length;i++){
            diffA[i]=diffA[i]+diffA[i-1];
        }
        for(int i:diffA) max=Math.max(max,i);
        return n-max;
    }
}

