class Solution:

	def MissingNo(self, matrix):
		status = 0
		status_f = 0
		sm_dia1 = 0
		sm_dia2 = 0
		for i in range(len(matrix)):
			for f in range(len(matrix)):
				if matrix[i][f] == 0:
					zero = [i, f]
		if 0 != zero[0]:
			sm = sum(matrix[0])
		else:
			sm = sum(matrix[1])
		for i in range(len(matrix)):
			sm_col = 0
			for j in range(len(matrix)):
				if zero[0] == i and zero[1] == j and (status_f == 0):
					status = 1
				sm_col += matrix[i][j]
			if sm_col != sm:
				if status == 0:
					return -1
				else:
					matrix[zero[0]][zero[1]] = sm - sm_col
					status = 0
					status_f = 1
		for i in range(len(matrix)):
			sm_dia1 += matrix[i][i]
			sm_dia2 += matrix[i][(i + 1) * -1]
		if sm_dia1 != sm or sm_dia2 != sm:
			return -1
		if matrix[zero[0]][zero[1]] <= 0:
			return -1
		return matrix[zero[0]][zero[1]]

