def read():
	(n, m) = map(int, input().split())
	return (n, m)

def solve(n, m):
	last = m % 10
	p = [0] * 11
	for i in range(1, 11):
		p[i] = last * i % 10
	dig_count = n // m
	(full_rounds, rest) = divmod(dig_count, 10)
	return full_rounds * sum(p[1:11]) + sum(p[1:rest + 1])
