def reservoirs(hills):
    hills_l, hills_r = range(len(hills)), range(len(hills)-1,-1,-1)
    placement_l, placement_r = [], []

    for i in hills_l:
        prev = hills_l[i-1] if i > 0 else float('-inf')
        nxt = hills_l[i+1] if i < len(hills)-1 else float('-inf')
        if hills[i] >= prev and hills[i] >= nxt or i == 0 or i == len(hills)-1:
            placement_l.append(i)

    for i in hills_r:
        prev = hills_r[i-1] if i > 0 else float('-inf')
        nxt = hills_r[i+1] if i < len(hills)-1 else float('-inf')
        if hills[i] >= prev and hills[i] >= nxt or i == 0 or i == len(hills)-1:
            placement_r.append(i)

    last = 0
    placement = placement_l+placement_r[::-1]
    placements = set()
    for index, hill in enumerate(placement):
        if last <= hill:
            placements.add(index)
            last = hill

    return(len(placements))


