class Solution:

	def hashString(self, S):
		S = S.split()
		chek = 'abcdefghijklmnopqrstuvwxyz1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ'
		has = 0
		step = 0
		for i in range(0, len(S)):
			for j in range(0, len(S[i])):
				step += j + chek.find(S[i][j])
		has = len(S) * step
		return has

