class Solution {
public:
    vector<int> partitionLabels(string S) {
        unordered_map<char, int> record;
        for(char c: S) record[c] ++;
        int l = 0, cur = 0;
        vector<int> res;
        while(cur < S.size()) {
            int c = 1;
            unordered_set<char> tmp;
            tmp.insert(S[cur]);
            record[S[cur]]--;
            if(record[S[cur]] == 0) c--;
            cur ++;
            while(c != 0) {
                if(!tmp.count(S[cur])) {
                    tmp.insert(S[cur]);
                    c++;
                }
                record[S[cur]]--;
                if(record[S[cur]] == 0) c--;
                cur ++;
            }
            res.push_back(cur - l);
            l = cur;
        }
        return res;
    }
};

