def sum_of_digits(x):
    return sum(int(digit) for digit in str(x))

def find_smallest_root(n):
    # We need to find the smallest x such that x^2 + s(x) * x - n = 0
    # We can start by checking values of x from 1 to a reasonable upper limit
    # Since x^2 + s(x) * x <= n, we can estimate an upper bound for x as sqrt(n)
    import math
    upper_bound = int(math.sqrt(n)) + 1

    for x in range(1, upper_bound):
        if x**2 + sum_of_digits(x) * x == n:
            return x
    return -1

