class Solution {
public:
    int sumOfDigits(vector<int>& A) {
        int min = INT_MAX;
        for (auto &n : A) { min = n < min ? n : min; }
        int sum = 0;
        while (min > 0) {
            int r = min % 10;
            sum += r;
            min /= 10;
        }
        return sum % 2 == 0 ? 1 : 0;
    }
};

import math
from functools import cmp_to_key
from collections import deque

def cmp(a, b):
	(la, ra) = a
	(lb, rb) = b
	if ra < rb:
		return -1
	if ra > rb:
		return 1
	if la < lb:
		return -1
	if la > lb:
		return 1
	return 0

def solve(n, LR):
	ans = []
	LR.sort(key=cmp_to_key(cmp))
	unused = []
	for i in range(1, n + 1):
		for (j, (l, r)) in enumerate(LR):
			if i >= l and i <= r:
				ans.append([i, l, r])
				break
		LR.pop(j)
	return ans

def main():
	ans = []
	t = int(input())
	for _ in range(t):
		n = int(input())
		LR = [tuple(map(int, input().split())) for _ in range(n)]
		ans.append(solve(n, LR))
	for a in ans:
		for (i, l, r) in a:
			print(f'{l} {r} {i}')
		print()
main()

class Solution {
public:
    bool checkIfExist(vector<int>& arr) {
        unordered_set<int> set;
        for (int num : arr) {
            if (set.find(num * 2)!= set.end() || (num % 2 == 0 && set.find(num / 2)!= set.end())) {
                return true;
            }
            set.insert(num);
        }
        return false;
    }
};

