class Solution:

	def btWithKleaves(self, root, k):
		nodes = []

		def rec(root):
			if not root:
				return 0
			if not root.left and (not root.right):
				return 1
			res = rec(root.left) + rec(root.right)
			if res == k:
				nodes.append(root.data)
			return res
		rec(root)
		return nodes if nodes else [-1]

