class E_ZHE_BIT {
 static final int MOD = (int)1e9+9;

 static long[][] C = new long[1001][1001];
 public static void main(String[] args) {
  Scanner scanner = new Scanner(System.in);

  for (int i = 0; i <= 1000; ++i) {
   C[i][0] = C[i][i] = 1;
   for (int j = 1; j < i; ++j) {
    C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % MOD;;
   }
  }

  int t = scanner.nextInt();

  for (int test = 0; test < t; ++test) {
   int n = scanner.nextInt();
   int k = scanner.nextInt();
   String s = scanner.next();

   boolean[] used = new boolean[n];
   int count0 = 0;
   int count1 = 0;
   for (int i = 0; i < n; ++i) {
    if (s.charAt(i) == '?') {
     used[i] = true;
     ++count0;
     ++count1;
    }
   }

   for (int attempt = 0; attempt < C[count0][k]; ++attempt) {
    char[] curr = new char[n];
    for (int i = 0; i < n; ++i) {
     if (used[i]) {
      curr[i] = s.charAt(i) == '0' ? '1' : '0';
     }
    }

    char[] prev = curr;

    int count = 0;
    for (int i = 0; i < n; ++i) {
     if (used[i] == false) {
      continue;
     }

     if (curr[i] != '?') {
      continue;
     }

     count += 1;
     for (int j = 1; j < k && i + j < n; ++j) {
      used[i + j] = true;
     }

     for (int j = 1; j < k && i - j + k <= n; ++j) {
      used[i - j + k] = true;
     }
    }

    boolean[] isBalanced = new boolean[k + 1];

    for (int i = 0; i + k <= n; ++i) {
     int count_ = 0;
     int count__ = 0;
     for (int j = 0; j < k; ++j) {
      if (prev[i + j] == '0') {
       ++count_;
      } else if (prev[i + j] == '1') {
       ++count__;
      }
     }

     isBalanced[count_] = true;

     if ((count1 - count__) % 2 == 1) {
      continue;
     } 

     for (int j = 0; j < k; ++j) {
      if (prev[i + j] == '?') {
       curr[i + j] = count__ > count_ ? '0' : '1';
      }
     }
    }

    boolean good = true;
    for (int i = 0; i <= k; ++i) {
     if (!isBalanced[i]) {
      good = false;
      break;
     }
    }

    if (good) {
     System.out.println("YES");
     System.out.println(new String(curr));
     break;
    } 
   }
   if (!good) {
    System.out.println("NO");
   }
  }
 }

 public static int getBinom(int n, int k) {
  if (k > n) {
   return 0;
  }

  return C[n][k];
 }
}

