#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int countValidTuples(const vector<int>& permutation) {
    int n = permutation.size();
    vector<int> counts(n, 0); // counts[i] will store the number of indices in (i, n] larger than permutation[i]

    // First pass to count the indices in (i, n] larger than permutation[i]
    for (int i = 0; i < n; ++i) {
        int value = permutation[i];
        counts[value - 1]++;
    }

    // Second pass to calculate the number of valid tuples for each index
    int total = 0;
    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n - 2; ++j) {
            for (int k = j + 1; k < n - 1; ++k) {
                for (int l = k + 1; l < n; ++l) {
                    // Check if the current quad meets the conditions
                    if (permutation[i] < permutation[k] && permutation[j] > permutation[l]) {
                        total += counts[k - 1];
                    }
                }
            }
        }
    }
    return total;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> permutation(n);
        for (int i = 0; i < n; ++i) {
            cin >> permutation[i];
        }
        cout << countValidTuples(permutation) << endl;
    }
    return 0;
}

