def maxUniqueSplit(s):
    def dfs(start, seen):
        if start == len(s):
            return 0
        ans = -1
        for end in range(start+1, len(s)+1):
            sub = s[start:end]
            if sub not in seen:
                seen.add(sub)
                next_res = dfs(end, seen)
                if next_res != -1:
                    ans = max(ans, 1 + next_res)
                seen.remove(sub)
        return ans

    return dfs(0, set())

print(maxUniqueSplit("ababccc"))  # returns 5
print(maxUniqueSplit("aba"))  # returns 2
print(maxUniqueSplit("aa"))  # returns 1

