class Solution {
public:
    string findSmallestRegion(vector<vector<string>>& regions, string region1, string region2) {
        string f1,f2;
        for(auto vc : regions){
            if(f1.size()&&f2.size()) break;
            for(auto s : vc){
                if(s == region1) f1 = vc[0];
                if(s == region2) f2 = vc[0];
            }
        }

        if(f1 == f2) return f1;
        else return findSmallestRegion(regions,f1,f2);
    }
};

