def digital_matchsticks(N, M, A):
    use_dict = {A[i]: 2 for i in range(M)}

    for i in range(N // 5):
        if '3' not in use_dict:
            break
        use_dict['3'] -= 1
        use_dict['5'] -= 3
        N -= 5

    for i in range(N // 7):
        if '7' not in use_dict:
            break
        use_dict['7'] -= 1
        N -= 7

    for i in range(N // 8):
        if '8' not in use_dict:
            break
        use_dict['8'] -= 1
        N -= 8

    for i in range(N // 4):
        if '4' not in use_dict:
            break
        use_dict['4'] -= 1
        N -= 4

   [res, use_dict] = [], {k: use_dict[k] + v for k, v in use_dict.items()}

    for k, v in use_dict.items():
        res.append(k * v)

    return ''.join(str(c) for c in res[::-1]) if N >= 0 else '0'

