    if n == 0:
        print("0 0 2")
        return
    for three in range(0, n // 3 + 1):
        for five in range(0, (n - three * 3) // 5 + 1):
            seven = (n - three * 3 - five * 5) // 7
            if three * 3 + five * 5 + seven * 7 == n:
                print(three, five, seven)
                return
    print("-1")

