from collections import deque

class Solution:

	def reverseWords(self, s):
		words = s.split('.')
		reversedSent = []
		for word in words:
			reversedWord = deque(word)
			reversedWord.reverse()
			reversedSent.append(''.join(reversedWord))
		return '.'.join(reversedSent)

