def minNumber(arr, N):

	def isprime(n):
		if n <= 1:
			return False
		for i in range(2, n):
			if n % i == 0:
				return False
		return True
	sum = 0
	for i in range(len(arr)):
		sum += arr[i]
	if isprime(sum):
		return 0
	else:
		for i in range(1, sum):
			if isprime(i + sum):
				break
		return i

