class Solution:
    def criticalRules(self, root, root2):
        # convert to lists from the root given to lists
        criticalRules = []
        list_a = self.convertToList(root)
        list_b = self.convertToList(root2)

        #intersect the two lists (to find the critical links together)
        for i in list_a:
            if i in list_b:
                criticalRules.append(i)
        return criticalRules

    def convertToList(self, root):
		stack = []
		criticalLeaves = []
		s = set()
		stackedNode = root
		while stack or s:
			while s:
				s.pop()
			while stackedNode:
				left = stackedNode.left
				right = stackedNode.right
				if left and right:
					stack.append(left)
					stack.append(right)
				elif not s:
					stackedNode.leftVisited = True
					if not left:
						s.add(stackedNode)
					stackedNode = stackedNode.left
				elif not right:
					stackedNode.rightVisited = True
					s.add(stackedNode)
					stackedNode = stackedNode.right
				else:
					stackedNode = stack.pop()
			criticalLeaves.append(stackedNode.data)
		return criticalLeaves
