public boolean checkPossibility(int[] nums) {
        int n = nums.length;
        int i = 0;
        while (i < n - 1) {
            if (nums[i] > nums[i + 1]) {
                int j = i + 1;
                while (j < n && nums[j] > nums[j - 1]) {
                    j++;
                }
                if (j == n) {
                    return false;
                }
                if (j == i + 2) {
                    nums[i] = nums[i + 1];
                } else {
                    nums[i] = nums[i + 1] = nums[i + 2];
                }
            }
            i++;
        }
        return true;
    }
}


