class Solution:

	def maxSumSequence(self, n, a):
		dp = [0] * n
		dp[0] = a[0]
		d = {}
		d[dp[0]] = [0]
		for i in range(1, n):
			s = 0
			for j in range(i - 1, -1, -1):
				if a[j] < a[i]:
					s = max(s, dp[j])
			dp[i] = s + a[i]
			if dp[i] not in d:
				d[dp[i]] = [i]
			else:
				d[dp[i]].append(i)
		r = max(dp)
		for k in d[r]:
			i = k
			break
		re = []
		while r >= 0:
			re.append(a[i])
			v = r
			r -= a[i]
			if r not in d:
				break
			for j in d[r]:
				if j < i and a[j] < a[i]:
					i = j
					break
			if v == r:
				break
		l = [int(i) for i in reversed(re)]
		return l

