def min_modifications(A, K):
    N = len(A)
    dp = [0] * (N - K + 1)

    for i in range(N - K + 1):
        dp[i] = sum(A[i:i+K])

    count = 0
    for i in range(N - K + 1):
        if dp[i] > 1:
            count += dp[i] - 1
            dp[i] = 1

    return count

