def minSwap(arr, n, k):
    window_size = sum(1 for i in arr if i <= k)
    min_swaps = n
    count = sum(1 for i in arr[:window_size] if i <= k)

    for i in range(n - window_size + 1):
        min_swaps = min(min_swaps, window_size - count)
        if i == n - window_size:
            break
        if arr[i] <= k:
            count -= 1
        if arr[i + window_size] <= k:
            count += 1

    return min_swaps

