#include <iostream>
#include <queue>
using namespace std;

int main() {
    int N;
    cin >> N;

    long long V[N];
    int T[N];
    for (int i = 0; i < N; ++i) {
        cin >> V[i];
    }
    for (int i = 0; i < N; ++i) {
        cin >> T[i];
    }

    priority_queue<long long, vector<long long>, greater<long long>> pq;
    long long accumulatedTemperature = 0;

    for (int i = 0; i < N; ++i) {
        long long totalMelted = 0;

        // Add the new snow pile adjusted by the accumulated temperature
        pq.push(V[i] + accumulatedTemperature);

        // Remove any piles that have completely melted
        while (!pq.empty() && pq.top() < accumulatedTemperature + T[i]) {
            totalMelted += pq.top() - accumulatedTemperature;
            pq.pop();
        }

        // Add the volume melted due to the current day's temperature
        totalMelted += T[i] * pq.size();

        // Prepare for the next day
        accumulatedTemperature += T[i];

        // Output the total melted volume for the current day
        cout << totalMelted << " ";
    }

    cout << endl;
    return 0;
}

