import itertools

def find_start_and_end(maze):
    start = end = None
    for i, row in enumerate(maze):
        for j, cell in enumerate(row):
            if cell == 'S':
                start = (i, j)
            elif cell == 'E':
                end = (i, j)
    return start, end

def move_robot(maze, start, direction_map, instruction):
    directions = [(-1, 0), (0, -1), (1, 0), (0, 1)]
    direction_values = {0: directions[0], 1: directions[1], 2: directions[2], 3: directions[3]}

    position = list(start)
    for move in instruction:
        direction = direction_values[direction_map[int(move)]]
        new_position = [position[0] + direction[0], position[1] + direction[1]]

        if 0 <= new_position[0] < len(maze) and 0 <= new_position[1] < len(maze[0]) and maze[new_position[0]][new_position[1]] != '#':
            position = new_position
        else:
            return False

        if position == list(end):
            return True

    return False

def count_successful_mappings(maze, instructions):
    directions = list(itertools.permutations(range(4)))
    successful_mappings = 0

    for direction_map in directions:
        if move_robot(maze, *find_start_and_end(maze), direction_map, instructions):
            successful_mappings += 1

    return successful_mappings

