def _sum(i):
    return sum(int(c) for c in str(i))

def _nsum(n):
    mult = 1
    while mult * 9 < n:
        mult *= 9
    res = str(n)
    while mult > 1:
        mult //= 9
        res = _nsum(mult) + _sum(mult) * "0"
    return res



