class ItemValue:
    def __init__(self, wt, val, ind):
        self.wt = wt
        self.val = val
        self.ind = ind
        self.ratio = val // wt

def fractionalKnapsack(W, arr, n):
    arr.sort(key=lambda x: x.ratio, reverse=True)
    total_value = 0.0
    for i in range(n):
        if arr[i].wt <= W:
            W -= arr[i].wt
            total_value += arr[i].val
        else:
            fraction = W / arr[i].wt
            total_value += arr[i].val * fraction
            break
    return total_value

class Solution {
public:
    int colorTheGrid(int m, int n) {
        const int MOD = 1e9 + 7;
        int valid[1 << (2 * m)];
        for (int mask = 0; mask < (1 << (2 * m)); ++mask) {
            bool validMask = true;
            for (int i = 0; i < 2 * m; ++i) {
                if (((mask >> i) & 1) && ((mask >> (i + 1)) & 1)) {
                    validMask = false;
                    break;
                }
            }
            valid[mask] = validMask;
        }

        int dp[1 << (2 * m)];
        memset(dp, 0, sizeof(dp));
        for (int mask = 0; mask < (1 << (2 * m)); ++mask) {
            if (valid[mask]) {
                dp[mask] = 1;
            }
        }

        for (int i = 1; i < n; ++i) {
            int dpNext[1 << (2 * m)];
            memset(dpNext, 0, sizeof(dpNext));
            for (int mask = 0; mask < (1 << (2 * m)); ++mask) {
                if (!valid[mask]) continue;
                for (int mask2 = 0; mask2 < (1 << (2 * m)); ++mask2) {
                    if (!valid[mask2]) continue;
                    bool validPair = true;
                    for (int j = 0; j < m; ++j) {
                        if (((mask >> (2 * j)) & 3) == ((mask2 >> (2 * j)) & 3)) {
                            validPair = false;
                            break;
                        }
                    }
                    if (validPair) {
                        dpNext[mask2] = (dpNext[mask2] + dp[mask]) % MOD;
                    }
                }
            }
            memcpy(dp, dpNext, sizeof(dp));
        }

        int ans = 0;
        for (int mask = 0; mask < (1 << (2 * m)); ++mask) {
            ans = (ans + dp[mask]) % MOD;
        }
        return ans;
    }
};

