def k_balanced(s, n, k):
    if n < k:
        return "NO"

    count = [0] * (n - k + 1)
    questions = [0] * (n - k + 1)

    for i in range(k):
        count[0] += (s[i] == '1') - (s[i] == '0')
        questions[0] += (s[i] == '?')

    for i in range(1, n - k + 1):
        count[i] = count[i - 1]
        questions[i] = questions[i - 1]
        if s[i - 1] == '1': 
            count[i] -= 1
        elif s[i - 1] == '0': 
            count[i] += 1
        if s[i - 1] == '?': 
            questions[i] -= 1
        if s[i + k - 1] == '1': 
            count[i] += 1
        elif s[i + k - 1] == '0': 
            count[i] -= 1
        if s[i + k - 1] == '?': 
            questions[i] += 1

        if abs(count[i]) > questions[i] or (count[i] + questions[i]) % 2 != 0:
            return "NO"

    return "YES"

