def solve(s):
    n = len(s)
    s = list(s)
    for i in range(n):
        if i % 2 == 0:
            s[i] = min(s[i], chr(ord(s[i]) + 1))
        else:
            s[i] = max(s[i], chr(ord(s[i]) - 1))
    return ''.join(s)

