public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[][] glasses = new int[n][2];
        for (int i = 0; i < n; i++) {
            glasses[i][0] = scanner.nextInt();
            glasses[i][1] = scanner.nextInt();
        }

        double[] result = new double[n];
        Arrays.sort(glasses, Comparator.comparingInt((int[] a) -> a[0]).thenComparingInt(a -> a[1]));

        for (int k = 1; k <= n; k++) {
            PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
            double totalWater = 0;
            for (int[] glass : glasses) {
                totalWater += glass[1];
            }
            for (int i = 0; i < n; i++) {
                pq.add(glasses[i][1]);
            }
            double toSpill = (totalWater - getTotalCapacity(glasses, k)) / 3.0;
            result[k - 1] = Math.min(totalWater - toSpill, getTotalCapacity(glasses, k));
            if (k > 1) {
                while (pq.size() > k) {
                    pq.poll();
                }
                result[k - 1] = computeMaxWater(pq, glasses, k);
            }
        }
        for (double d : result) {
            System.out.printf("%.10f ", d);
        }
    }

    private static double computeMaxWater(PriorityQueue<Integer> pq, int[][] glasses, int k) {
        double maxWater = 0;
        int nonFullCount = 0;
        for (int i = 0; i < k; i++) {
            maxWater += Math.min(glasses[i][0], pq.peek());
            if (glasses[i][0] > pq.peek()) {
                nonFullCount++;
            }
            pq.poll();
        }
        double overflow = Math.max(0, maxWater - getTotalCapacity(glasses, k));
        return maxWater - overflow / (1 + nonFullCount);
    }

    private static int getTotalCapacity(int[][] glasses, int k) {
        int capacity = 0;
        for (int i = 0; i < k; i++) {
            capacity += glasses[i][0];
        }
