std::vector<int> findLosers(int n, int k) {
    std::vector<bool> received(n, false);
    std::vector<int> losers;
    int current = 0;
    int step = 1;

    while (!received[current]) {
        received[current] = true;
        current = (current + step * k) % n;
        step++;
    }

    for (int i = 0; i < n; ++i) {
        if (!received[i]) {
            losers.push_back(i + 1);
        }
    }

    return losers;
}

int main() {
    int n, k;
    std::cin >> n >> k;
    std::vector<int> result = findLosers(n, k);
    for (int loser : result) {
        std::cout << loser << " ";
    }
    std::cout << std::endl;
    return 0;
}

