class PandemoniumPoint(unittest.TestCase):
    def expected(self, arr):
        pro=math.prod(arr)
        return 1 if pro==0 else max(1, (pro // max(pro,sum(arr)))-2)

    def actual(self, arr):
        res = 0
        while sum(arr) != 0 or math.prod(arr) != 0:
            res += 1
            for x in range(len(arr)):
                if arr[x] % 2 != 0:
                    arr[x] += 1
            for x in range(len(arr)):
                if arr[x] % 2 != 0:
                    arr[x] -= 1
        return res

    def test(self):
        function = lambda arr: sorted(list(set([self.expected(arr), self.actual(arr)])))
        print(function([2, 1, -2, 3]))
        print(function([-2, 0, 1, 2]))
        print(function([2, -1, 0]))
        print(function([2, 1, -1]))
        print(function([2, 3]))


