class Solution {
public:
    string rankTeams(vector<string>& votes) {
        int max_num = votes[0].size();
        vector<int> team_freq(max_num, 0);
        map<char, int> count;
        for (int i = 0; i < max_num; ++i) {
            count[votes[0][i]] = 0;
        }
        for (auto& team : votes[0]) {
            count[team] = 0;
        }

        for (int i = 1; i < votes.size(); ++i) {
            for (int j = 0; j < max_num; ++j) {
                if (votes[i][j] != votes[i][0]) {
                    --team_freq[j];
                } else {
                    ++team_freq[j];
                }
                ++count[votes[i][j]];
            }
        }

        vector<char> res(votes[0].begin(), votes[0].end());
        auto comp = [](char c1, char c2) {
            for (int i = 0; i < max_num; i++) {
                if (count[c1] > count[c2]) {
                    return false;
                }
                if (count[c2] > count[c1]) {
                    return true;
                }
            }
            return c1 < c2;
        };
        sort(res.begin(), res.end(), comp);
        return string(res.begin(), res.end());
    }
