from collections import defaultdict

def solve(strings, queries):
    mem = defaultdict(int)
    for s in strings:
        mem[s] += 1

    for q in queries:
        found = False
        for i in range(len(q)):
            for c in 'abc':
                if c != q[i]:
                    new_q = q[:i] + c + q[i+1:]
                    if new_q in mem:
                        found = True
                        break
            if found:
                break
        print('YES' if found else 'NO')


