def mcd(a, b):
	if a == 0 and b == 0:
		print('ERROR')
	elif a == 0:
		return b
	elif b == 0:
		return a
	elif a >= b:
		return mcd(b, a % b)
	else:
		return mcd(a, b % a)

def floor(a):
	return int(a // 1)

def inverso(a, n):
	if mcd(a, n) > 1:
		raise Exception('No existe inverso')
	else:
		(s0, t0, s1, t1, r0, r1) = (1, 0, 0, 1, n, a)
	while r1 > 1:
		aux_s = s0 - floor(r0 / r1) * s1
		s0 = s1
		s1 = aux_s
		aux_t = t0 - floor(r0 / r1) * t1
		t0 = t1
		t1 = aux_t
		r0 = r1
		r1 = s1 * n + t1 * a
	if t1 < 0:
		t1 += n
	return t1
