    public int findDerangement(int n) {
        if(n == 1) {
            return 0;
        }
        if(n == 2) {
            return 1;
        }
        long dp[] = new long[n + 1];
        dp[1] = 0 + k1;
        dp[2] = 1 + k1;

        for(int i = 3; i <= n; i++) {
            long p = i - 1;
            long temp = (((p*dp[i - 2]) % k1) + ((p*dp[i - 1]) % k1)) % k1;
            dp[i] = temp + k1;
        }

        return (int)dp[n];
    }

