def solve_game(n, a):
    dp = [[-1] * (n + 1) for _ in range(n + 1)]

    def is_valid(i, j):
        return 1 <= j <= n and (i - j) % a[i] == 0

    def dfs(i, j):
        if dp[i][j] != -1:
            return dp[i][j]

        if i == n:
            return 1

        dp[i][j] = 0
        for k in range(1, n + 1):
            if is_valid(i, k) and dfs(i + 1, k):
                dp[i][j] = 1
                break

        return dp[i][j]

    for j in range(1, n + 1):
        if dfs(0, j):
            print("A")
        else:
            print("B")

