from collections import deque

def solve():
    n, m = inp()

    g = [[] for _ in range(n)]
    for _ in range(m):
        u, v = inp()
        g[u-1].append(v-1)
        g[v-1].append(u-1)
    parent = [-1] * n
    link = [i for i in range(n)]

    def find(x):
        if link[x] != x:
            link[x] = find(link[x])
        return link[x]

    def unite(x, y):
        x = find(x)
        y = find(y)
        if x == y:
            return
        if g[x] < g[y]:
            x, y = y, x
        link[y] = x
