class Solution {
    private static boolean isVowel(final char c) {
        switch (c) {
            case 'a': case 'e': case 'i': case 'o': case 'u': return true;
            default: return false;
        }
    }

    public int beautifulSubstrings(String str, int k) {
        final char[] s = str.toCharArray();
        final int[] vCnt = new int[s.length + 1];
        final int[] cCnt = new int[s.length + 1];
        for(int i = 0; i < s.length; i++) {
            if (isVowel(s[i])) {
                vCnt[i + 1] = vCnt[i] + 1;
                cCnt[i + 1] = cCnt[i];
            } else {
                vCnt[i + 1] = vCnt[i];
                cCnt[i + 1] = cCnt[i] + 1;
            }
        }
        int ans = 0;
        for(int start = 0; start <= s.length; start++) {
            for (int end = start + 1; end <= s.length; end++) {
                final int vcnt = vCnt[end] - vCnt[start], ccnt = cCnt[end] - cCnt[start];
                if (vcnt == ccnt && vcnt * ccnt % k == 0) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

