from typing import *
class Solution:
    def specialSwap(self, A):
        gap = [math.inf]*len(A)
        for fmt in range(1,(1<<len(A))+1):
            nex = -1
            for i in range(len(A)):
                if fmt&(1<<i):
                    nex = i
            if nex==-1:
                continue
            gap[nex-1] = min(gap[nex-1], nex-i)
        gap.pop()
        for fmt in range(1,(1<<len(A))+1):
            pre = 0
            nex = -1
            for i in reversed(range(len(A))):
                if fmt&(1<<i):
                    nex = i
                pre += gap[nex+1]
            gap[nex+1] = min(gap[nex+1], i-pre)
        return sum(gap)

