void solve() {

	ll n, x, y, ans = 0;

	cin >> n >> x >> y;

	vector<ll> a(n + 1);

	forn(i, n) {

		cin >> a[i];

	}

	sort(a.begin() + 1, a.end());

	forn(i, n) {

		if (x >= a[i]) {

			ans++;

			x++;

			if (x == y) {

				cout << ans << '\n';

				return;

			}

			continue;

		}

		ll d = 2 * (i - 1) - n;

		if (d <= 0) {

			cout << -1 << '\n';

			return;

		}

		ll dist = max(0LL, min(a[i], y) - x);

		ll k = dist / d;

		x += k * d;

		ans += n * k;

		if (x == y) {

			cout << ans << '\n';

			return;

		}

		if (x == a[i]) {

			ans++;

			x++;

			if (x == y) {

				cout << ans << '\n';

				return;

			}

			continue;

		}

		x -= n - i + 1;

		ans += n - i + 1;

		ans += min(i - 1, y - x);

		x += min(i - 1, y - x);

		if (x == y) {

			cout << ans << '\n';

			return;

		}

		if (x < min(a[i], y)) {

			cout << "lol" << '\n';

			return;

		}

		x++;

		ans++;

		if (x == y) {

			cout << ans << '\n';

			return;

		}

	}

	ll k = (y - x) / n;

	ans += k * n + (y - x) % n;

	cout << ans << '\n';

}



