def insertInMid(head, node):
	slow = head
	fast = head
	l = 1
	while fast != None and fast.next != None:
		if fast.next.next != None:
			l += 2
		elif fast.next != None:
			l += 1
		else:
			break
		temp = slow
		slow = slow.next
		fast = fast.next.next
	if l % 2 == 0:
		slow = temp
	node.next = slow.next
	slow.next = node
	return head

