def oranges_wasted(n, b, d, a):
    waste = count = 0
    for ai in a:
        if ai > b:
            if count + ai <= d:
                count += ai
            else:
                waste += 1
                count = ai
        else:
            count += ai
        if count == d + 1:
            waste += 1
            count = 0
    return waste

