    if len(prices) < k+1:
        return None
    if len(prices) == k+1:
        return max(prices)-min(prices)
    if len(prices) == k+2:
        return [a - b for (a, b) in zip(prices[1:],prices[0:-1])]

    prices = findBestPrice(k,prices[0:-1]) + findBestPrice(k,prices[1:])
