import sys

class modint:
    def __init__(self, x):
        self.x = x % modint.mod

    def __str__(self):
        return str(self.x)

    def __add__(self, other):
        return modint(self.x + other.x)

    def __sub__(self, other):
        return modint(self.x - other.x)

    def __mul__(self, other):
        return modint(self.x * other.x)

    def __truediv__(self, other):
        return modint(self.x * pow(other.x, modint.mod - 2, modint.mod))

    def __pow__(self, other):
        return modint(pow(self.x, other.x, modint.mod))

    def __eq__(self, other):
        return self.x == other.x

    def __ne__(self, other):
        return self.x != other.x

    def __lt__(self, other):
        return self.x < other.x

    def __le__(self, other):
        return self.x <= other.x

    def __gt__(self, other):
        return self.x > other.x

    def __ge__(self, other):
        return self.x >= other.x

    def __radd__(self, other):
        return modint(other.x + self.x)

    def __rsub__(self, other):
        return modint(other.x - self.x)

    def __rmul__(self, other):
        return modint(other.x * self.x)

    def __rtruediv__(self, other):
        return modint(other.x * pow(self.x, modint.mod - 2, modint.mod))

    def __rpow__(self, other):
        return modint(pow(other.x, self.x, modint.mod))

    def __iadd__(self, other):
        self.x += other.x
        return self

    def __isub__(self, other):
        self.x -= other.x
        return self

    def __imul__(self, other):
        self.x *= other.x
        return self

    def __itruediv__(self, other):
        self.x *= pow(other.x, modint.mod - 2, modint.mod)
        return self

    def __ipow__(self, other):
        self.x = pow(self.x, other.x, modint.mod)
        return self

    @classmethod
    def mod(cls, x):
        return cls.mod_

    @classmethod
    def setmod(cls, x):
        cls.mod_ = x

