def DFS(G, s):

	def visit(G, parent, vertexes, visited, u):
		visited[u] = True
		for v in G[u]:
			if not visited[v]:
				vertexes.append(v)
				parent[v] = u
				visit(G, parent, vertexes, visited, v)
	n = len(G)
	visited = [False] * n
	parent = [None] * n
	vertexes = [s]
	visit(G, parent, vertexes, visited, s)
	for i in range(1, n):
		if not visited[i]:
			visit(G, parent, vertexes, visited, i)
	return vertexes

