int greatestCommonDivisor(int a, int b) {
    int getMax = 0;
    int getMin = 0;
    if (a > b) {
        getMax = a;
        getMin = b;
    } else {
        getMax = b;
        getMin = a;
    }

    for (int i = 0; i<= getMin / 2; ++i) {
        if (getMin % i == 0 && getMax % i == 0) {
            getMin = i;
        }
    }

    return getMin;
}

