# Solution 

def ReFormatString(S, K):
    S = S.upper()
    res = ''
    for i, c in enumerate(S):
        if c == '-':
            continue
        res += c
        if (i + 1) % K == 0 and (i + 1) != len(S):
            res += "-"
    if len(res) > len(S):
        res = res[:-1]
    return res

