def can_reach_planet(p_x, p_y, s):
    x, y = 0, 0
    stack = []
    for order in s:
        if order == 'U':
            y += 1
            stack.append('U')
        elif order == 'D':
            y -= 1
            stack.append('D')
        elif order == 'R':
            x += 1
            stack.append('R')
        elif order == 'L':
            x -= 1
            stack.append('L')
    while stack:
        if (x, y) == (p_x, p_y):
            return True
        if x > 0 and stack and stack[-1] == 'L':
            x -= 1
            stack.pop()
        elif x < 0 and stack and stack[-1] == 'R':
            x += 1
            stack.pop()
        elif y > 0 and stack and stack[-1] == 'D':
            y -= 1
            stack.pop()
        elif y < 0 and stack and stack[-1] == 'U':
            y += 1
            stack.pop()
        else:
            return False
    return (x, y) == (p_x, p_y)

